contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 amount) public {
        require(amount > 0);
        c.XBornID(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(amount <= balBefore);
        uint256 supBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 distBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        c.burn(amount); if (__ESBMC_reverted()) return;
        assert(
            c.totalSupply() == supBefore - amount &&
            c.totalDistributed() == distBefore - amount &&
            c.balanceOf(address(this)) == balBefore - amount
        );
    }
    receive() external payable {}
}

